describe('ToolRegistry', () => {
  describe('schema compilation', () => {
    it('compiles a valid static schema at register time', () => {
      const registry = new ToolRegistry();

      expect(() => {
        registry.register(
          {
            name: 'valid_tool',
            description: 'A valid tool',
            inputSchema: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          async () => 'result'
        );
      }).not.toThrow();
    });

    it('throws at register time naming the tool when a static schema is invalid', () => {
      const registry = new ToolRegistry();

      expect(() => {
        registry.register(
          {
            name: 'broken_tool',
            description: 'Invalid schema',
            inputSchema: {
              type: 'object',
              properties: {location: {type: 'not-a-valid-type'}},
            },
          },
          async () => 'unreachable'
