private getOrCompileValidator(schema: Record<string, unknown>): ReturnType<Ajv['compile']> {
  const cached = this.functionSchemaValidators.get(schema);
  if (cached) {
    return cached;
  }
  const validator = this.compileSchema(schema);
  this.functionSchemaValidators.set(schema, validator);
  return validator;
}

private formatValidationError(errors: Parameters<typeof this.ajv.compile>[0][] | null | undefined): string {
  if (!errors || errors.length === 0) {
    return 'Validation failed';
  }
  const messages = errors.map(error => {
    const path = error.instancePath || '/';
    const keyword = error.keyword;
    let message = `${path}: `;

    if (keyword === 'required' && error.params && typeof error.params === 'object' && 'missingProperty' in error.params) {
      message += `missing required property "${String(error.params.missingProperty)}"`;
    } else if (keyword === 'type' && error.params && typeof error.params === 'object' && 'type' in error.params) {
      message += `must be of type ${String(error.params.type)}`;
    } else {
      message += `failed validation (${keyword})`;
    }

    return message;
  });
  return messages.join('; ');
}

