  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ReturnType<Ajv['compile']>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
  private readonly functionSchemaValidators = new WeakMap<Record<string, unknown>, ReturnType<Ajv['compile']>>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(schema: Record<string, unknown>): ReturnType<Ajv['compile']> {
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      throw new Error(`Failed to compile schema: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ReturnType<Ajv['compile']> | undefined;

    if (typeof definition !== 'function') {
      try {
        staticValidator = this.compileSchema(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Tool "${resolved.name}": ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

